import type { BotSkill } from '../ai/types';

export interface RatedMatchPlayer {
  id: string;
  rating: number;
  place: number;
}

export interface RatingChange {
  id: string;
  previousRating: number;
  rating: number;
  delta: number;
  expectedScore: number;
  actualScore: number;
}

export interface RatingOptions {
  kFactor?: number;
}

const rookie: BotSkill = { aimError: 0.2, powerError: 0.18, simulationSamples: 32, riskTolerance: 0.18, shortcutAwareness: 0.08, planningDepth: 1 };
const legend: BotSkill = { aimError: 0.025, powerError: 0.025, simulationSamples: 108, riskTolerance: 0.82, shortcutAwareness: 0.94, planningDepth: 3 };

function expectedAgainst(rating: number, opponentRating: number): number {
  return 1 / (1 + 10 ** ((opponentRating - rating) / 400));
}

/** Elo for a whole mini-golf table: every place is compared against every opponent. */
export function calculateMultiplayerElo(players: readonly RatedMatchPlayer[], options: RatingOptions = {}): RatingChange[] {
  if (players.length < 2) return players.map(player => ({ id: player.id, previousRating: player.rating, rating: player.rating, delta: 0, expectedScore: 0.5, actualScore: 0.5 }));
  const kFactor = options.kFactor ?? 32;
  return players.map(player => {
    let expectedTotal = 0;
    let actualTotal = 0;
    for (const opponent of players) {
      if (opponent.id === player.id) continue;
      expectedTotal += expectedAgainst(player.rating, opponent.rating);
      actualTotal += player.place < opponent.place ? 1 : player.place === opponent.place ? 0.5 : 0;
    }
    const divisor = players.length - 1;
    const expectedScore = expectedTotal / divisor;
    const actualScore = actualTotal / divisor;
    const delta = Math.round(kFactor * (actualScore - expectedScore));
    return { id: player.id, previousRating: player.rating, rating: Math.max(0, player.rating + delta), delta, expectedScore, actualScore };
  });
}

function smoothstep(value: number): number {
  const clamped = Math.min(1, Math.max(0, value));
  return clamped * clamped * (3 - 2 * clamped);
}

function interpolate(from: number, to: number, amount: number): number {
  return from + (to - from) * amount;
}

/** Maps Elo continuously to bot capability, avoiding abrupt rank-boundary behaviour. */
export function botSkillForRating(rating: number): BotSkill {
  const amount = smoothstep((rating - 700) / 1800);
  return {
    aimError: interpolate(rookie.aimError, legend.aimError, amount),
    powerError: interpolate(rookie.powerError, legend.powerError, amount),
    simulationSamples: Math.round(interpolate(rookie.simulationSamples, legend.simulationSamples, amount)),
    riskTolerance: interpolate(rookie.riskTolerance, legend.riskTolerance, amount),
    shortcutAwareness: interpolate(rookie.shortcutAwareness, legend.shortcutAwareness, amount),
    planningDepth: Math.round(interpolate(rookie.planningDepth, legend.planningDepth, amount)),
  };
}
